import Foundation

// Compiled with the unchanged production LearnedModel, never a view/window or
// the real HTTP client. Responses are generated by the real private engine.
@MainActor final class WispClient {
    struct Pending {
        let reply: [String: Any]?
        let continuation: CheckedContinuation<[String: Any]?, Never>
    }
    static var replies: [[String: Any]?] = []
    static var changes: [[String: Bool]] = []
    static var requests: [Pending] = []
    static var names: [String] = []
    static var gets: [Pending] = []
    static var getReply: [String: Any]?
    static var holdGet = false
    static var settingsReply: [String: Any]? = ["enabled": true]
    static var historyReply: [String: Any]?
    static var historyReplies: [[String: Any]?] = []
    static var historyRequests: [Pending] = []
    static var historyBodies: [[String: Any]] = []
    static var historyGets: [Pending] = []
    static var holdHistoryGet = false
    static var checks = 0

    func setBehaviorSignal(_ name: String, enabled: Bool) async -> [String: Any]? {
        let index = Self.requests.count
        precondition(index < Self.replies.count, "Unexpected write")
        precondition(Self.changes[index] == [name: enabled], "Write order differs from captured UI intent")
        Self.names.append(name)
        return await withCheckedContinuation {
            Self.requests.append(Pending(reply: Self.replies[index], continuation: $0))
        }
    }
    func behaviorSettings() async -> [String: Any]? { Self.settingsReply }
    func behaviorGet(_ name: String) async -> [String: Any]? {
        if name == "email-history" {
            if Self.holdHistoryGet {
                return await withCheckedContinuation {
                    Self.historyGets.append(Pending(reply: Self.historyReply, continuation: $0))
                }
            }
            return Self.historyReply
        }
        if name == "signals" {
            if Self.holdGet {
                return await withCheckedContinuation {
                    Self.gets.append(Pending(reply: Self.getReply, continuation: $0))
                }
            }
            return Self.getReply
        }
        return name == "patterns" ? ["patterns": [[String: Any]]()] : [:]
    }
    func behaviorEmailHistoryControl(_ body: [String: Any]) async -> [String: Any]? {
        let index = Self.historyRequests.count
        precondition(index < Self.historyReplies.count, "Unexpected history write")
        Self.historyBodies.append(body)
        return await withCheckedContinuation {
            Self.historyRequests.append(Pending(reply: Self.historyReplies[index], continuation: $0))
        }
    }
    func behaviorPredictions(day: String) async -> [String: Any]? { ["predictions": []] }
    func behaviorHistoryControl(_ source: String, command: String) async -> Bool {
        fatalError("History mutation forbidden")
    }
    func setBehaviorPatternStatus(_ id: String, status: String) async -> Bool {
        fatalError("Pattern mutation forbidden")
    }
    static func wait(_ predicate: () -> Bool) async {
        for _ in 0..<10000 {
            if predicate() { return }
            await Task.yield()
        }
        fatalError("Controlled continuation did not arrive")
    }
    static func settle() async { for _ in 0..<100 { await Task.yield() } }
    static func release(_ index: Int) {
        let item = requests[index]
        item.continuation.resume(returning: item.reply)
    }
    static func releaseGet(_ index: Int) {
        let item = gets[index]
        item.continuation.resume(returning: item.reply)
    }
    static func releaseHistory(_ index: Int) {
        let item = historyRequests[index]
        item.continuation.resume(returning: item.reply)
    }
    static func releaseHistoryGet(_ index: Int) {
        let item = historyGets[index]
        item.continuation.resume(returning: item.reply)
    }
    static func check(_ condition: @autoclosure () -> Bool, _ message: String) {
        precondition(condition(), message)
        checks += 1
    }
    static func reset(_ scenario: [String: Any]) {
        replies = (scenario["replies"] as! [[String: Any]]).map { $0 }
        changes = scenario["changes"] as! [[String: Bool]]
        requests = []; names = []; gets = []
        getReply = scenario["initial"] as? [String: Any]
        holdGet = false
        settingsReply = ["enabled": true]
        historyReply = nil; historyReplies = []; historyRequests = []; historyBodies = []
        historyGets = []; holdHistoryGet = false
    }
}

@main struct BehaviorSignalSettingsRegression {
    @MainActor static func main() async throws {
        let data = try Data(contentsOf: URL(fileURLWithPath: CommandLine.arguments[1]))
        let wire = try JSONSerialization.jsonObject(with: data) as! [String: Any]
        let cases = wire["cases"] as! [String: [String: Any]]
        let names = wire["names"] as! [String]
        let cross = cases["cross"]!
        let same = cases["same"]!
        let bounded = cases["bounded"]!
        let crossReplies = cross["replies"] as! [[String: Any]]
        let sameReplies = same["replies"] as! [[String: Any]]

        // Preserve the original desired-contract reproducer, accepting either a
        // serialized transport or the original independently delayed replies.
        WispClient.reset(cross)
        let model = LearnedModel()
        WispClient.check(names.allSatisfy { model.signalValue($0) == nil }, "Cold settings are unknown")
        await model.refresh()
        WispClient.check(model.signalState == .ready, "Full initial snapshot confirms settings")
        let first = Task { await model.setSignal("activity", enabled: true) }
        await WispClient.wait { WispClient.requests.count == 1 }
        let second = Task { await model.setSignal("notes", enabled: true) }
        await WispClient.settle()
        if WispClient.requests.count == 2 {
            // This legal transport order reproduced the original privacy bug.
            WispClient.release(1)
            await second.value
            WispClient.release(0)
        } else {
            WispClient.release(0)
            await WispClient.wait { WispClient.requests.count == 2 }
            WispClient.release(1)
        }
        await first.value
        await second.value
        await WispClient.settle()
        WispClient.check(model.signalValue("notes") == true,
                         "Current Notes consent was overwritten by an older Activity reply")
        WispClient.check(model.signalValue("activity") == true, "Unrelated consent survives")

        // Same-source on/off: caller cancellation cannot drop a captured off.
        WispClient.reset(same)
        let sameModel = LearnedModel()
        await sameModel.refresh()
        sameModel.setSignal("notes", enabled: true)
        await WispClient.wait { WispClient.requests.count == 1 }
        let off = Task { sameModel.setSignal("notes", enabled: false) }
        off.cancel()
        await off.value
        await WispClient.settle()
        WispClient.check(WispClient.requests.count == 1, "Only one write may be in flight")
        WispClient.check(sameModel.signalState == .saving && sameModel.signalValue("notes") == nil,
                         "An optimistic or intermediate setting is not confirmed")
        WispClient.release(0)
        await WispClient.wait { WispClient.requests.count == 2 }
        WispClient.check(sameModel.signalValue("notes") == nil, "Intermediate enable remains pending")
        WispClient.release(1)
        await WispClient.wait { sameModel.signalState != .saving }
        WispClient.check(sameModel.signalValue("notes") == false, "Latest off intent wins after cancellation")

        // Work is bounded by the nine sources even under a rapid burst. The
        // newest pending value for each source replaces its superseded intent.
        WispClient.reset(bounded)
        let burst = LearnedModel()
        await burst.refresh()
        burst.setSignal("activity", enabled: true)
        await WispClient.wait { WispClient.requests.count == 1 }
        for i in 0..<1000 {
            for name in names { burst.setSignal(name, enabled: i % 2 == 0) }
        }
        burst.setSignal("unrecognized-source", enabled: true)
        await WispClient.settle()
        WispClient.check(WispClient.requests.count == 1, "Burst creates no parallel writes")
        for index in 0...names.count {
            await WispClient.wait { WispClient.requests.count == index + 1 }
            WispClient.check(burst.signalState == .saving, "Queue stays explicitly pending")
            WispClient.release(index)
        }
        await WispClient.wait { burst.signalState != .saving }
        WispClient.check(WispClient.requests.count == 10, "At most one in-flight plus nine pending writes")
        WispClient.check(names.allSatisfy { burst.signalValue($0) == false }, "Burst preserves all latest intents")
        WispClient.check(burst.signals["default_block_minutes"] as? Int == 30, "Backend default duration survives")

        // A GET started before a mutation cannot overwrite any later consent,
        // whether it finishes during or after the write, or after a newer GET.
        for finishDuringWrite in [false, true] {
            WispClient.reset(cross)
            WispClient.holdGet = true
            let stale = LearnedModel()
            let old = Task { await stale.refresh() }
            await WispClient.wait { WispClient.gets.count == 1 }
            stale.setSignal("activity", enabled: true)
            await WispClient.wait { WispClient.requests.count == 1 }
            stale.setSignal("notes", enabled: true)
            if finishDuringWrite {
                WispClient.releaseGet(0); await old.value
                WispClient.check(stale.signalState == .saving, "Old GET cannot confirm a pending write")
            }
            WispClient.release(0)
            await WispClient.wait { WispClient.requests.count == 2 }
            WispClient.release(1)
            await WispClient.wait { stale.signalState != .saving }
            if !finishDuringWrite {
                WispClient.getReply = crossReplies[1]
                let fresh = Task { await stale.refresh() }
                await WispClient.wait { WispClient.gets.count == 2 }
                WispClient.releaseGet(1); await fresh.value
                WispClient.releaseGet(0); await old.value
            }
            WispClient.check(stale.signalValue("notes") == true && stale.signalValue("activity") == true,
                             "Stale refresh completion cannot roll back source consent")
        }

        WispClient.reset(same)
        let during = LearnedModel()
        await during.refresh()
        during.setSignal("notes", enabled: true)
        await WispClient.wait { WispClient.requests.count == 1 }
        await during.refresh()
        WispClient.check(WispClient.gets.isEmpty && during.signalState == .saving,
                         "Refresh during mutation withholds the source read")
        WispClient.release(0)
        await WispClient.wait { during.signalState != .saving }
        WispClient.getReply = sameReplies[0]
        await during.refresh()
        WispClient.check(during.signalValue("notes") == true, "Post-write fresh GET confirms current state")

        // Broken transport/schema/acknowledgement must never look disabled.
        var partial = sameReplies[0]
        partial["settings"] = ["notes": true]
        var numericBool = sameReplies[0]
        var numericSettings = numericBool["settings"] as! [String: Any]
        numericSettings["notes"] = 1
        numericBool["settings"] = numericSettings
        var boolMinutes = sameReplies[0]
        var minuteSettings = boolMinutes["settings"] as! [String: Any]
        minuteSettings["default_block_minutes"] = true
        boolMinutes["settings"] = minuteSettings
        var fractionalMinutes = sameReplies[0]
        minuteSettings["default_block_minutes"] = 30.5
        fractionalMinutes["settings"] = minuteSettings
        var unboundedMinutes = sameReplies[0]
        minuteSettings["default_block_minutes"] = 121
        unboundedMinutes["settings"] = minuteSettings
        var noEpoch = sameReplies[0]
        noEpoch.removeValue(forKey: "epoch")
        let mismatched = same["initial"] as! [String: Any]
        let invalid: [[String: Any]?] = [nil, [:], partial, numericBool, boolMinutes,
                                       fractionalMinutes, unboundedMinutes, noEpoch, mismatched]
        for bad in invalid {
            WispClient.reset(same)
            WispClient.replies[0] = bad
            let failed = LearnedModel()
            await failed.refresh()
            failed.setSignal("notes", enabled: true)
            await WispClient.wait { WispClient.requests.count == 1 }
            WispClient.release(0)
            await WispClient.wait { failed.signalState != .saving }
            WispClient.check(failed.signalState == .unavailable && names.allSatisfy { failed.signalValue($0) == nil },
                             "Failed/malformed consent is explicitly unavailable for every source")
            WispClient.check(!failed.error.isEmpty && failed.signals.isEmpty, "Failure is visible and cached claims are cleared")
            WispClient.getReply = sameReplies[0]
            await failed.refresh()
            WispClient.check(failed.signalValue("notes") == true && failed.error.isEmpty,
                             "Fresh current read recovers an ambiguous applied write and clears its error")
            failed.setSignal("notes", enabled: false)
            await WispClient.wait { WispClient.requests.count == 2 }
            WispClient.release(1)
            await WispClient.wait { failed.signalState != .saving }
            WispClient.check(failed.signalValue("notes") == false && failed.error.isEmpty, "Explicit retry recovers normally")
        }

        WispClient.reset(cross)
        WispClient.replies[0] = nil
        let mixed = LearnedModel()
        mixed.setSignal("activity", enabled: true)
        await WispClient.wait { WispClient.requests.count == 1 }
        mixed.setSignal("notes", enabled: true)
        WispClient.release(0)
        await WispClient.wait { WispClient.requests.count == 2 }
        WispClient.release(1)
        await WispClient.wait { mixed.signalState != .saving }
        WispClient.check(mixed.signalState == .unavailable, "Later success cannot silently confirm a failed intent")
        WispClient.getReply = crossReplies[1]
        await mixed.refresh()
        WispClient.check(mixed.signalValue("notes") == true && mixed.signalValue("activity") == true,
                         "Explicit GET recovers mixed outcomes")
        for bad in [nil, [:], partial, numericBool, noEpoch] as [[String: Any]?] {
            WispClient.getReply = bad
            await mixed.refresh()
            WispClient.check(mixed.signalState == .unavailable && mixed.signalValue("notes") == nil,
                             "Failed/malformed refresh never defaults to off")
        }
        WispClient.settingsReply = nil
        await mixed.refresh()
        WispClient.check(mixed.signalState == .unavailable, "Unreachable master settings cannot confirm source consent")
        WispClient.settingsReply = ["enabled": true]
        WispClient.getReply = crossReplies[1]
        await mixed.refresh()
        WispClient.check(mixed.signalState == .ready && mixed.signalValue("notes") == true, "Refresh recovery")
        await historyControls(wire["history"] as? [String: Any] ?? historyFixture(), scenario: cross)
        print("synthetic signal settings checks passed: \(WispClient.checks) assertions")
    }

    static func historyFixture() -> [String: Any] {
        func status(_ revision: Int, _ state: String) -> [String: Any] {
            ["version": 1, "session": "synthetic-session", "permission_revision": 1,
             "available": true, "accounts": [["account_id": "configured-one",
                 "connection_revision": "connection-one", "account_set_revision": "set-one",
                 "control_revision": revision, "state": state, "counts": [String: Any]()]]]
        }
        return ["initial": status(0, "off"), "started": status(1, "running"),
                "paused": status(2, "paused"), "scope": ["start": 1791964800, "end": 1792051200,
                    "selection": "mailbox", "message_cap": 100]]
    }

    @MainActor static func historyControls(_ wire: [String: Any], scenario: [String: Any]) async {
        let initial = wire["initial"] as! [String: Any]
        let started = wire["started"] as! [String: Any]
        let paused = wire["paused"] as! [String: Any]
        let scope = wire["scope"] as! [String: Any]
        let account = (initial["accounts"] as! [[String: Any]])[0]["account_id"] as! String
        func setup() {
            WispClient.reset(scenario)
            var signals = WispClient.getReply!
            var settings = signals["settings"] as! [String: Any]
            settings["email"] = true
            signals["settings"] = settings
            WispClient.getReply = signals
            WispClient.historyReply = initial
        }
        setup()
        WispClient.historyReplies = [started, paused]
        let ordered = LearnedModel()
        await ordered.refresh()
        WispClient.check(ordered.emailHistoryState == .ready && WispClient.historyBodies.isEmpty,
                         "History GET never starts acquisition")
        ordered.emailHistoryControl(account: account, command: "start", scope: scope)
        await WispClient.wait { WispClient.historyRequests.count == 1 }
        for _ in 0..<1000 { ordered.emailHistoryControl(account: account, command: "pause") }
        WispClient.check(ordered.emailHistoryState == .saving, "Pending history intent is unconfirmed")
        WispClient.releaseHistory(0)
        await WispClient.wait { WispClient.historyRequests.count == 2 }
        WispClient.check(ordered.emailHistoryState == .saving, "Intermediate Start ACK is not displayed")
        WispClient.check(WispClient.historyBodies[1]["command"] as? String == "pause" &&
                         (WispClient.historyBodies[1]["revision"] as? NSNumber)?.intValue == 1,
                         "Latest Pause follows acknowledged control revision")
        WispClient.releaseHistory(1)
        await WispClient.wait { ordered.emailHistoryState != .saving }
        WispClient.check(ordered.emailHistoryAccounts[0]["state"] as? String == "paused" &&
                         WispClient.historyRequests.count == 2, "History burst is coalesced and Pause wins")

        // A connection/session change after an ambiguous Start cannot carry a
        // queued explicit Start over to a newly connected account authority.
        for changedField in ["session", "permission_revision", "connection_revision", "account_set_revision"] {
            setup()
            WispClient.historyReplies = [nil, started]
            let changed = LearnedModel()
            await changed.refresh()
            changed.emailHistoryControl(account: account, command: "start", scope: scope)
            await WispClient.wait { WispClient.historyRequests.count == 1 }
            changed.emailHistoryControl(account: account, command: "start", scope: scope)
            var rebound = initial
            if changedField == "session" { rebound[changedField] = "new-session" }
            else if changedField == "permission_revision" { rebound[changedField] = 999 }
            else {
                var rows = rebound["accounts"] as! [[String: Any]]
                rows[0][changedField] = "new-source-revision"
                rebound["accounts"] = rows
            }
            WispClient.historyReply = rebound
            WispClient.releaseHistory(0)
            await WispClient.settle()
            // Release unexpected write so a failing implementation is still quiescent.
            if WispClient.historyRequests.count > 1 { WispClient.releaseHistory(1) }
            await WispClient.wait { changed.emailHistoryState != .saving }
            WispClient.check(WispClient.historyRequests.count == 1 && changed.emailHistoryState == .unavailable,
                             "Queued Start cannot transfer to changed \(changedField)")
        }

        setup()
        WispClient.historyReplies = [started]
        WispClient.changes = [["email": false]]
        WispClient.replies = [scenario["initial"] as? [String: Any]]
        let revoked = LearnedModel()
        await revoked.refresh()
        revoked.emailHistoryControl(account: account, command: "start", scope: scope)
        await WispClient.wait { WispClient.historyRequests.count == 1 }
        revoked.setSignal("email", enabled: false)
        await WispClient.wait { WispClient.requests.count == 1 }
        WispClient.releaseHistory(0)
        await WispClient.settle()
        WispClient.check(revoked.emailHistoryState == .unavailable && revoked.emailHistory.isEmpty,
                         "Late Start ACK cannot restore history after consent intent")
        WispClient.release(0)
        await WispClient.wait { revoked.signalState != .saving }

        setup()
        WispClient.holdHistoryGet = true
        let stale = LearnedModel()
        let oldRead = Task { await stale.refresh() }
        await WispClient.wait { WispClient.historyGets.count == 1 }
        WispClient.holdHistoryGet = false
        await stale.refresh()
        WispClient.historyReplies = [started]
        stale.emailHistoryControl(account: account, command: "start", scope: scope)
        await WispClient.wait { WispClient.historyRequests.count == 1 }
        WispClient.releaseHistory(0)
        await WispClient.wait { stale.emailHistoryState != .saving }
        WispClient.releaseHistoryGet(0)
        await oldRead.value
        WispClient.check(stale.emailHistoryAccounts[0]["state"] as? String == "running",
                         "Stale pre-Start GET cannot roll back acknowledged history state")

        var numericAvailable = started
        numericAvailable["available"] = 1
        var duplicate = started
        duplicate["accounts"] = (started["accounts"] as! [[String: Any]]) + (started["accounts"] as! [[String: Any]])
        var negativeCount = started
        var countRows = negativeCount["accounts"] as! [[String: Any]]
        countRows[0]["counts"] = ["fetched": -1]
        negativeCount["accounts"] = countRows
        for bad in [nil, initial, numericAvailable, duplicate, negativeCount] as [[String: Any]?] {
            setup()
            WispClient.historyReplies = [bad]
            let failed = LearnedModel()
            await failed.refresh()
            failed.emailHistoryControl(account: account, command: "start", scope: scope)
            await WispClient.wait { WispClient.historyRequests.count == 1 }
            WispClient.releaseHistory(0)
            await WispClient.wait { failed.emailHistoryState != .saving }
            WispClient.check(failed.emailHistoryState == .unavailable && failed.emailHistory.isEmpty,
                             "Malformed, stale or ambiguous history ACK is unknown")
            WispClient.historyReply = started
            await failed.refresh()
            WispClient.check(failed.emailHistoryState == .ready && failed.error.isEmpty,
                             "Fresh history read recovers uncertainty and clears its error")
        }
    }
}
